import { IngestPipeline } from "@514labs/moose-lib";

// User Activity Event data model
export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number;
}

// Ingestion pipeline with optimized table ordering for our query patterns:
// 1. Activity counts per user over a date range -> order by user_id, event_ts
// 2. Total duration per action type -> include action in ordering
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["user_id", "event_ts", "action"]
  },
  stream: true,
  ingestApi: true,
});

