const fs = require('fs');
const https = require('https');
const http = require('http');

// Read and parse the CSV data
const csvData = fs.readFileSync('/data/samples/user_activity_sample.csv', 'utf8');
const lines = csvData.trim().split('\n');
const headers = lines[0].split(',');

// Convert CSV to JSON objects
const jsonData = lines.slice(1).map(line => {
  const values = line.split(',');
  const record = {};

  headers.forEach((header, index) => {
    let value = values[index];

    if (header === 'event_ts') {
      // Keep as ISO string for proper Date parsing
      record[header] = value;
    } else if (header === 'duration_ms') {
      // Convert to number, default to 0 if null/empty
      record[header] = value ? parseFloat(value) : 0;
    } else {
      record[header] = value;
    }
  });

  return record;
});

console.log('Sample records to be sent:');
console.log(JSON.stringify(jsonData.slice(0, 2), null, 2));
console.log(`Total records: ${jsonData.length}`);

// Send data to Moose ingestion endpoint
async function sendData() {
  const options = {
    hostname: 'localhost',
    port: 4000,
    path: '/ingest/UserActivity',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    }
  };

  for (let i = 0; i < jsonData.length; i++) {
    const record = jsonData[i];

    try {
      await new Promise((resolve, reject) => {
        const req = http.request(options, (res) => {
          let data = '';
          res.on('data', (chunk) => data += chunk);
          res.on('end', () => {
            if (res.statusCode >= 200 && res.statusCode < 300) {
              console.log(`✓ Sent record ${i + 1}/${jsonData.length}: ${record.event_id}`);
              resolve();
            } else {
              console.error(`✗ Failed to send record ${i + 1}: ${res.statusCode} - ${data}`);
              reject(new Error(`HTTP ${res.statusCode}: ${data}`));
            }
          });
        });

        req.on('error', reject);
        req.write(JSON.stringify(record));
        req.end();
      });
    } catch (error) {
      console.error(`Error sending record ${i + 1}:`, error.message);
    }
  }

  console.log('Data loading completed!');
}

sendData();

